        var indiceDrive = mensagemOriginal.IndexOf(":\\", StringComparison.Ordinal);
        if (indiceDrive > 0 && char.IsLetter(mensagemInterpretada[indiceDrive - 1]))
        {
            var diretorioExplicito = mensagemOriginal[(indiceDrive - 1)..].Trim();
            if (Directory.Exists(diretorioExplicito))
            {
                ciclo.Adicionar("diretorio_projeto", diretorioExplicito);
            }
        }

        var resolucao =
            _resolvedorConversa.Resolver(
                mensagemInterpretada,
                ciclo,
                _contextoProjeto,
                intencao);

        if (resolucao.TemIntencao)
        {
            intencao = resolucao.Intencao!;

            ciclo.Adicionar(
                "intencao_detectada",
                $"{intencao.Ferramenta}:{intencao.Operacao}");

            ciclo.Adicionar(
                "intencao_confianca",
                intencao.Confianca.ToString(
                    CultureInfo.InvariantCulture));

            ciclo.Adicionar(
                "intencao_evidencia",
