        // O GerenciadorConversa apenas preserva o contexto da rodada.
        ciclo.Adicionar(
            "memoria:processamento",
            "delegado_ao_decisor");

        var confirmacaoPendente =
            _processadorConfirmacao.ObterPendente(ciclo);

        if (confirmacaoPendente is not null &&
            _processadorConfirmacao.EhConfirmacao(mensagemInterpretada))
        {
            _processadorConfirmacao.Confirmar(ciclo);
            ciclo.Adicionar("confirmacao_autorizada", "sim");
            ciclo.Adicionar("confirmacao_ferramenta", confirmacaoPendente.Ferramenta);
            ciclo.Adicionar("confirmacao_operacao", confirmacaoPendente.Operacao);

            intencao = new IntencaoDetectada
            {
                Ferramenta = confirmacaoPendente.Ferramenta,
                Operacao = confirmacaoPendente.Operacao,
                Confianca = 1.0,
                Identificada = true,
                Evidencia = "confirmacao explicita da operacao pendente"
            };

            ciclo.Adicionar(
                "intencao_detectada",
                $"{intencao.Ferramenta}:{intencao.Operacao}");
        }
        else if (confirmacaoPendente is not null &&
                 _processadorConfirmacao.EhCancelamento(mensagemInterpretada))
        {
            _processadorConfirmacao.Cancelar(ciclo);
            ciclo.Adicionar("confirmacao_resultado", "cancelada");
            ciclo.Adicionar("ultima_resposta", "Operacao cancelada.");
            _historico.AdicionarAssistente("Operacao cancelada.");
            ciclo.ConsolidarEm(contexto);
            return new Resposta { Conteudo = "Operacao cancelada." };
        }

        var instrucao =
            new Instrucao
            {
                Conteudo = correcaoSolicitada ? mensagemResolvida : mensagemOriginal
