    private bool PrepararCorrecaoDeResposta(
        string mensagemOriginal,
        ContextoCiclo ciclo,
        ref string mensagemResolvida)
    {
        if (!EhContestacaoResposta(mensagemOriginal))
            return false;

        var mensagens = _historico.Listar().ToArray();
        if (mensagens.Length < 3)
            return false;

        for (var i = mensagens.Length - 2; i >= 1; i--)
        {
            if (!string.Equals(mensagens[i].Papel, "kayron", StringComparison.OrdinalIgnoreCase))
                continue;

            for (var j = i - 1; j >= 0; j--)
            {
                if (!string.Equals(mensagens[j].Papel, "usuario", StringComparison.OrdinalIgnoreCase))
                    continue;

                mensagemResolvida = mensagens[j].Conteudo.Trim();
                ciclo.Adicionar("correcao_resposta:ativa", "sim");
                ciclo.Adicionar("correcao_resposta:pergunta_original", mensagemResolvida);
                ciclo.Adicionar("correcao_resposta:resposta_contestada", mensagens[i].Conteudo.Trim());
                ciclo.Adicionar("correcao_resposta:memoria_bloqueada", "sim");
                return true;
            }
        }

        return false;
    }

    private static bool EhContestacaoResposta(string texto)
    {
        var normalizado = texto
            .Trim()
            .ToLowerInvariant()
            .Replace("á", "a").Replace("à", "a").Replace("ã", "a").Replace("â", "a")
            .Replace("é", "e").Replace("ê", "e").Replace("í", "i")
            .Replace("ó", "o").Replace("ô", "o").Replace("õ", "o")
            .Replace("ú", "u").Replace("ç", "c");

        return normalizado.Contains("resposta errada", StringComparison.Ordinal) ||
               normalizado.Contains("resposta esta errada", StringComparison.Ordinal) ||
               normalizado.Contains("resposta incorreta", StringComparison.Ordinal) ||
               normalizado.Contains("isso esta errado", StringComparison.Ordinal) ||
               normalizado.Contains("isso esta incorreto", StringComparison.Ordinal) ||
               normalizado.Contains("voce errou", StringComparison.Ordinal) ||
               normalizado.Contains("nao esta correto", StringComparison.Ordinal) ||
               normalizado.Contains("esta incorreta", StringComparison.Ordinal);
    }
    private void ConsolidarMemoriaExplicita(string mensagem)
    {
        var texto = mensagem.Trim();
        if (texto.Length < 8) return;

        var textoNormalizado = texto
            .Normalize(NormalizationForm.FormD)
            .Where(c => CharUnicodeInfo.GetUnicodeCategory(c) != UnicodeCategory.NonSpacingMark)
            .ToArray();
        var textoAnalise = new string(textoNormalizado).ToLowerInvariant();

        if (textoAnalise.Contains("novas formas de perguntar") &&
            textoAnalise.Contains("identificar padroes") &&
            textoAnalise.Contains("classificacao"))
        {
            _memoriaAprendida.Aprender(
                "capacidade_aprendizado_variacoes_perguntas",
                "Analisar novas formas de perguntar, identificar padrões e sugerir classificação; registrar o padrão somente após o aprendizado ser executado.",
                "capacidade",
                4,
                false,
                "agente",
                new[] { "aprendizado", "variacoes", "padroes", "classificacao" });
            return;
        }

        var nome = ExtrairDepoisDe(texto, "meu nome ÃƒÆ’Ã‚Â©") ?? ExtrairDepoisDe(texto, "eu me chamo");
        if (!string.IsNullOrWhiteSpace(nome))
        {
            _memoriaAprendida.Aprender("nome_usuario", nome);
            return;
        }

        var projeto = ExtrairDepoisDe(texto, "meu projeto ÃƒÆ’Ã‚Â©");
        if (!string.IsNullOrWhiteSpace(projeto))
        {
            _memoriaAprendida.Aprender("projeto_usuario", projeto);
            return;
        }

        var instrucao = ExtrairDepoisDe(texto, "lembre que") ?? ExtrairDepoisDe(texto, "nÃƒÆ’Ã‚Â£o esqueÃƒÆ’Ã‚Â§a que");
        if (!string.IsNullOrWhiteSpace(instrucao))
        {
            var chave = "fato_" + Math.Abs(StringComparer.OrdinalIgnoreCase.GetHashCode(instrucao));
            _memoriaAprendida.Aprender(chave, instrucao);
        }
    }

    private static string? ExtrairDepoisDe(string texto, string marcador)
    {
        var indice = texto.IndexOf(marcador, StringComparison.OrdinalIgnoreCase);
        if (indice < 0) return null;
        var valor = texto[(indice + marcador.Length)..].Trim().TrimEnd('.', '!', '?', ';');
        return valor.Length is >= 2 and <= 500 ? valor : null;
    }
